import {GET_ITEMS, ADD_ITEM, DELETE_ITEM,ITEMS_LOADING} from '../actions/types'; 

const initialState = {
    items:[
  
    ],
    loading:false //represents posts that come from the action.  Action uses the fetch request
    //item:{} //will represent single posts that we add
} 
export default function(state=initialState, action) {
    switch(action.type) {
        case GET_ITEMS: 
        return {
            ...state,
            items: action.payload,
            loading:false
        };
        case DELETE_ITEM: 
        return {
            ...state, 
            items:state.items.filter(item=>item._id!==action.payload) 
        };
        case ADD_ITEM: 
        return {
            ...state,
            items: [action.payload,...state.items]
        };
        case ITEMS_LOADING: 
        return {
            ...state,
            loading:true
        };
        default: return state;
    }
}//evaluates what type  we are deaaling with
